const TAGREGEX = new RegExp(".*\\p{L}.*", "u");

const segmenter = new Intl.Segmenter('en', {granularity: 'grapheme'});

function countGraphemeClusters(str) {
    return [...segmenter.segment(str)].length;
}

/**
 * Javadoc generated by ChatGPT
 * Validates a password against several criteria:
 * - Must include at least one uppercase letter, one lowercase letter, one number, and one special character
 * - Must be at least 8 characters long
 * - Must not exceed 255 grapheme clusters
 * - If a confirmation password is provided, must match the password
 * - Must not contain the user's first name, last name, or email (case-insensitive)
 *
 * @param {string} password - The password string to validate
 * @param {string} [passwordConfirm] - Optional confirmation password to check if it matches
 * @param {string} [firstName] - Optional first name to check if included in password
 * @param {string} [lastName] - Optional last name to check if included in password
 * @param {string} [email] - Optional email to check if included in password
 * @returns {string[]|false} Returns an array of error keys if invalid, or false if the password is valid
 */
function validatePassword(password, passwordConfirm, firstName, lastName,
        email) {
    // regex courtesy of https://uibakery.io/regex-library/password
    const passwordRegex = new RegExp(
            /^(?=.*?\p{Lu})(?=.*?\p{Ll})(?=.*?\p{N})(?=.*?[\p{P}\p{S}])[\p{L}\p{M}\p{N}\p{P}\p{S}]{8,}$/gu);

    const errors = [];

    if (!passwordRegex.test(password) || password.length === 0) {
        errors.push("invalidPassword");
    }

    if (countGraphemeClusters(password) > 255) {
        errors.push("passwordLength");
    }

    if (passwordConfirm !== undefined && password !== passwordConfirm) {
        errors.push("passwordsMatching");
    }

    if (firstName !== undefined || lastName !== undefined || email
            !== undefined) {
        const passwordLower = password.toLowerCase();
        const passwordContainsFirstName = typeof firstName === "string"
                && firstName.trim() !== "" && passwordLower.includes(
                        firstName.trim().toLowerCase());
        const passwordContainsLastName = typeof lastName === "string"
                && lastName.trim() !== "" && passwordLower.includes(
                        lastName.trim().toLowerCase());
        const passwordContainsEmail = typeof email === "string"
                && email.trim() !== "" && passwordLower.includes(
                        email.trim().toLowerCase());
        if (passwordContainsFirstName
                || passwordContainsLastName || passwordContainsEmail) {
            errors.push("containsUserDetails");
        }
    }
    return errors.length > 0 ? errors : false
}

/**
 * Javadoc generated by ChatGPT
 * Sets up event listeners and validation logic for the password and confirmation fields on the page.
 * Validates the password according to the rules in validatePassword and displays relevant error messages
 * using the provided custom error messages.
 *
 * Listens to the 'blur' and 'input' events on the password field and the 'input' event on the confirmation field.
 *
 * @param {Object<string, string>} customErrors - An object mapping error keys (e.g. "invalidPassword") to custom error message strings
 * @returns {function} A function that when called runs the password validation and returns true if valid, false otherwise
 */
function setupPasswordValidation(customErrors) {
    let passwordBlurred = false;

    function runPasswordValidation() {
        const passwordInput = document.getElementById("password");
        const confirmInput = document.getElementById("confirm");
        const passwordError = document.getElementById("passwordError");
        const confirmError = document.getElementById("confirmError");

        const firstNameInput = document.getElementById("firstname");
        const lastNameInput = document.getElementById("lastname");
        const emailInput = document.getElementById("email");

        let firstName;
        if (firstNameInput) {
            firstName = firstNameInput.value;
        }
        let lastName;
        if (lastNameInput) {
            lastName = lastNameInput.value;
        }
        let email;
        if (emailInput) {
            email = emailInput.value;
        }

        const password = passwordInput.value;
        const confirm = confirmInput.value;

        const errors = validatePassword(password, confirm, firstName, lastName,
                email);

        passwordInput.classList.remove("is-invalid");
        confirmInput.classList.remove("is-invalid");
        passwordError.style.display = "none";
        confirmError.style.display = "none";

        if (!errors) {
            return true;
        }

        const passwordRelatedErrors = ["invalidPassword", "passwordLength",
            "containsUserDetails"];
        const foundPasswordErrors = errors.filter(
                e => passwordRelatedErrors.includes(e));
        if (foundPasswordErrors.length > 0) {
            passwordInput.classList.add("is-invalid");
            passwordError.innerText = foundPasswordErrors
            .map(e => customErrors[e])
            .join(". ") + ".";
            passwordError.style.display = "block";
        }

        if (errors.includes("passwordsMatching")) {
            confirmInput.classList.add("is-invalid");
            confirmError.innerText = customErrors["passwordsMatching"];
            confirmError.style.display = "block";
        }

        return false;
    }

    document.addEventListener("DOMContentLoaded", () => {
        const passwordInput = document.getElementById("password");
        const confirmInput = document.getElementById("confirm");

        // This section provides nice blur behavior so the fields don't error on first type
        passwordInput.addEventListener("blur", () => {
            passwordBlurred = true;
            runPasswordValidation();
        });

        passwordInput.addEventListener("input", () => {
            if (passwordBlurred) {
                runPasswordValidation();
            }
        });

        confirmInput.addEventListener("input", runPasswordValidation);
    });

    return runPasswordValidation;
}

/**
 * Validates an email
 * @param email
 * @param checkUniqueEmail boolean - set as false to skip check if email already
 * in use (on the login page).
 * @returns empty string if valid, relevant error message if invalid
 */
async function validateEmail(email, checkUniqueEmail) {
    // regex courtesy of https://www.baeldung.com/java-email-validation-regex modified by chatGPT
    const emailRegex = new RegExp(
            /^[\p{L}\p{M}\w!#$%&'*+/=?`{|}~^+\-]+(?:\.[\p{L}\p{M}\w!#$%&'*+/=?`{|}~^+\-]+)*@(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\.)+[a-zA-Z]{2,6}$/gu
    );
    let errorMessages = [];

    if (!emailRegex.test(email) || email.trim().length === 0) { // check valid
        errorMessages.push("Email address must " +
                "be in the form 'jane@doe.nz'");
    }
    if (countGraphemeClusters(email) > 255) {
        errorMessages.push("Email must be 255 characters long or less");
    }
    if (checkUniqueEmail) {
        const emailInUse = await validateEmailInUse(email);
        if (emailInUse) {
            errorMessages.push("This email address is already in use");
        }
    }

    if (errorMessages.length > 0) {
        return errorMessages.join(". ") + ".";
    } else {
        return "";
    }
}

/**
 * Validates a first name
 * @param firstName
 * @returns empty string if valid, relevant error message if invalid
 */
function validateFirstName(firstName) {
    const nameRegex = new RegExp(/^[\p{L}\p{M}.,' ་-]*$/gu);
    let errorMessages = []

    if (firstName.trim().length === 0) { // check empty
        errorMessages.push("First name cannot be empty");
    }
    if (countGraphemeClusters(firstName) > 64) { // check too long
        errorMessages.push("First name must be 64 characters long or less");
    }
    if (!nameRegex.test(firstName)) { // check valid
        errorMessages.push("First name must only include " +
                "letters, spaces, hyphens or apostrophes");
    }

    if (errorMessages.length > 0) {
        return errorMessages.join(". ") + ".";
    } else {
        return "";
    }
}

/**
 * Validates a last name
 * @param lastName
 * @returns empty string if valid, relevant error message if invalid
 */
function validateLastName(lastName) {
    const nameRegex = new RegExp(/^[\p{L}\p{M}.,' ་-]*$/gu);
    let errorMessages = []

    if (!nameRegex.test(lastName) && lastName.trim().length !== 0) { // check valid or empty
        errorMessages.push("Last name must only include " +
                "letters, spaces, hyphens or apostrophes");
    }
    if (countGraphemeClusters(lastName) > 64) {
        errorMessages.push("Last name must be 64 characters long or less");
    }

    if (errorMessages.length > 0) {
        return errorMessages.join(". ") + ".";
    } else {
        return "";
    }
}

/**
 * Applies error styling and the error message to an invalid field. Removes error styling and message for a valid field
 * @param invalidField
 * @param errorField
 * @param errorMessage
 * @returns true if there is no error message, false if there is an error message
 */
function addError(invalidField, errorField, errorMessage) {
    errorField.textContent = errorMessage
    if (errorMessage !== "") {
        errorField.classList.remove('d-none')
        errorField.style.display = "inline"
        invalidField.classList.add('is-invalid')
        return false
    }
    errorField.style.display = "none"
    invalidField.classList.remove('is-invalid')
    return true
}

/**
 * Validates the first name field against 3 criteria:
 * 1. Is not empty
 * 2. Is not > 64 chars
 * 3. Does not contain illegal chars
 * @returns {boolean} true if valid
 */
function validateFirstNameRegistrationPage() {
    let firstNameInput = document.getElementById("firstname");
    let firstName = firstNameInput.value;
    let errorField = document.getElementById("firstNameError");

    const errorText = validateFirstName(firstName)
    return addError(firstNameInput, errorField, errorText)
}

/**
 * Validates the last name field against 3 criteria:
 * 1. Is not > 64 chars
 * 2. Does not contain illegal chars
 * @returns {boolean} true if valid
 */
function validateLastNameRegistrationPage() {
    let lastNameInput = document.getElementById("lastname");
    let lastName = lastNameInput.value;
    let errorField = document.getElementById("lastNameError");
    const errorText = validateLastName(lastName)
    return addError(lastNameInput, errorField, errorText)
}

/**
 * Validates the email name field against 2 criteria:
 * 1. Is correct email form
 * 2. Is the email unique
 * @returns {boolean} true if valid
 */
async function validateEmailRegistrationPage() {
    let emailInput = document.getElementById("email");
    let email = emailInput.value;
    let errorField = document.getElementById("emailError");
    const errorText = await validateEmail(email, true);
    return addError(emailInput, errorField, errorText)
}

/**
 * Validates the email field.
 * @returns {boolean} true if valid
 */
async function validateEmailLoginPage() {
    let emailInput = document.getElementById("email");
    let email = emailInput.value;
    let errorField = document.getElementById("emailError");
    const errorText = await validateEmail(email, false);
    return addError(emailInput, errorField, errorText)
}

/**
 * Run all validation for registration page
 */
async function validateRegistrationPage() {
    // Run all validation functions
    const firstNameValid = validateFirstNameRegistrationPage();
    const lastNameValid = validateLastNameRegistrationPage();
    const emailValid = validateEmailRegistrationPage();
    return firstNameValid && lastNameValid && emailValid;
}

