/**
 * Validates the email field for the edit profile page. Removes the email in use
 * error if it exists. Adds the error border to the field if the email is invalid
 *
 * @returns {boolean} truth value of an error existing
 */
async function validateEmailEditProfilePage() {
    const emailInput = document.getElementById("email");
    const email = emailInput.value;
    const errorField = document.getElementById("emailError");
    const errorText = await validateEmail(email, true);
    return addError(emailInput, errorField, errorText);
}

function validateTagName() {
    const tagInput = document.getElementById("tagName");
    const tagName = tagInput.value;
    const errorField = document.getElementById("tagError");

    if (!TAGREGEX.test(tagName) && tagName !== "") {
        errorField.textContent = "tags must contain letters";
        tagInput.classList.add("is-invalid");
    } else {
        errorField.textContent = "";
        tagInput.classList.remove("is-invalid");
    }
}

/**
 * Request information from the server side to check if the email is
 * already in use.
 *
 * @param email - email address to check
 * @return Promise<boolean> - truth value of email already in use
 */
function validateEmailInUse(email) {
    const url = "register/emailInUse?email=" + encodeURIComponent(email);

    return fetch(url, {
        method: "GET"
    })
    .then(res => res.json())
    .then(res => {
        return res.emailInUse === "true";
    })
    .catch(
            err => {
                console.error("Error checking email in use", err);
                return false;
            }
    );
}

